function validate(input) {
  const [t, calls] = input;
  if (!Number.isInteger(t) || t < 0 || t > 1000) return 't must be an integer from 0 to 1000.';
  if (!Array.isArray(calls) || calls.length < 1 || calls.length > 10) return 'Give 1 to 10 calls.';
  let previous = 0;
  for (const call of calls) {
    if (!call || typeof call !== 'object' || !Number.isInteger(call.t) || call.t < 0 || call.t > 1000) return 'Each call needs a time t from 0 to 1000.';
    if (!Array.isArray(call.inputs) || call.inputs.length > 10 || !call.inputs.every(Number.isInteger)) return 'Each call needs inputs: a list of at most 10 integers.';
    if (call.t < previous) return 'List the calls in time order.';
    previous = call.t;
  }
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [t, calls] = input, runs = [];
  const fn = (...args) => { runs.push({ t: Date.now(), inputs: args }); kit.trace(`fn(${args.join(', ')}) runs`); };
  const throttled = solve(fn, t);
  if (typeof throttled !== 'function') throw new Error('throttle must return a function.');
  for (const call of calls) setTimeout(() => { kit.trace(`throttled(${call.inputs.join(', ')}) is called`); throttled(...call.inputs); }, call.t);
  // The last saved arguments run at most t ms after the last call, so every run is over by then.
  return new Promise(resolve => setTimeout(() => resolve(runs), calls[calls.length - 1].t + t + 1));
}

