function throttle(fn, t) {
  // Track when the current waiting period ends, and set a timer only once something is saved in it.
  let periodEnd = -1;
  let saved = null;
  const release = () => {
    const args = saved;
    saved = null;
    fn(...args);
    periodEnd = Date.now() + t;
  };
  return function (...args) {
    const now = Date.now();
    if (now > periodEnd) {
      fn(...args);
      periodEnd = now + t;
      return;
    }
    if (saved === null) setTimeout(release, periodEnd - now);
    saved = args;
  };
}

